<?php
namespace App\Modules\Sales\Domain\Entities;
use DateTimeImmutable;
final class Product
{public function __construct(private string $id,private string $partnerId,private string $sku,private string $name,private string $category,private int $basePriceMinor,private int $baseCostMinor,private string $currency='MXN',private bool $active=true,private DateTimeImmutable $createdAt=new DateTimeImmutable(),private ?DateTimeImmutable $deletedAt=null){}public function getId():string{return $this->id;}public function getPartnerId():string{return $this->partnerId;}public function getSku():string{return $this->sku;}public function getName():string{return $this->name;}public function getCategory():string{return $this->category;}public function getBasePriceMinor():int{return $this->basePriceMinor;}public function getBaseCostMinor():int{return $this->baseCostMinor;}public function getBasePrice():float{return $this->basePriceMinor/100;}public function getBaseCost():float{return $this->baseCostMinor/100;}public function getCurrency():string{return $this->currency;}public function isActive():bool{return $this->active&&$this->deletedAt===null;}public function getCreatedAt():DateTimeImmutable{return $this->createdAt;}public function getDeletedAt():?DateTimeImmutable{return $this->deletedAt;}}
